import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/en/mcp-externo.png",r="/pro-agent-hub-installer/capturas/en/mcp-proprio.png",g=JSON.parse('{"title":"MCP services","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/mcp.md","filePath":"en/interface/mcp.md","lastUpdated":1787856241000}'),i={name:"en/interface/mcp.md"};function l(h,e,c,p,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="mcp-services" tabindex="-1">MCP services <a class="header-anchor" href="#mcp-services" aria-label="Permalink to &quot;MCP services&quot;">​</a></h1><p><strong>MCP</strong> (Model Context Protocol) is the standard by which an agent gains tools that did not come built in. This screen registers two rather different kinds of record, and the choice is made at creation time:</p><ul><li><strong>External</strong> — a third party&#39;s MCP server, which you consume by URL.</li><li><strong>Own</strong> — a server <em>you</em> write here, and the platform publishes.</li></ul><h2 id="external" tabindex="-1">External <a class="header-anchor" href="#external" aria-label="Permalink to &quot;External&quot;">​</a></h2><p><img src="'+s+'" alt="mcp-externo"></p><p>All it takes is the transport, the URL and the timeout. Nothing runs on your installation — the platform simply talks to the address you gave.</p><p>Once saved, link the service to an agent on the agent&#39;s Tools tab.</p><h2 id="own" tabindex="-1">Own <a class="header-anchor" href="#own" aria-label="Permalink to &quot;Own&quot;">​</a></h2><p><img src="'+r+'" alt="mcp-proprio"></p><p>Here you write the tools in Python and the platform brings up an MCP server for them, in a separate process — a slow MCP service never ties up an API request.</p><h3 id="tools-tab" tabindex="-1">Tools tab <a class="header-anchor" href="#tools-tab" aria-label="Permalink to &quot;Tools tab&quot;">​</a></h3><p>Each top-level function becomes a tool. <strong>Write no decorator and no route</strong>: the platform wraps the functions and assembles <code>register_tools</code> itself. The name, the signature and the docstring are the contract the model reads to decide when to call it.</p><p>The scope carries <code>log()</code> and the data, system and integration operations — see <a href="/pro-agent-hub-installer/en/funcoes/mcp_tools">Own MCP</a>.</p><h3 id="helpers-tab" tabindex="-1">Helpers tab <a class="header-anchor" href="#helpers-tab" aria-label="Permalink to &quot;Helpers tab&quot;">​</a></h3><p>Support code: <code>import</code> statements, constants and shared functions. <strong>Nothing here becomes a tool</strong>, even a top-level function. It is the line between &quot;what the model may call&quot; and &quot;what your code uses internally&quot;.</p><h3 id="authentication-tab" tabindex="-1">Authentication tab <a class="header-anchor" href="#authentication-tab" aria-label="Permalink to &quot;Authentication tab&quot;">​</a></h3><p>Three keys, and it is worth knowing what each one opens:</p><ul><li><strong>Fixed token</strong> — a secret the caller presents. This is what you hand to a client outside the platform.</li><li><strong>Accept workflow token</strong> — lets workflows and planners of the installation itself call the service without a token of their own.</li><li><strong>Accept user authentication</strong> — lets a signed-in user call it, respecting their groups.</li></ul><p>Turning all three off leaves the service published and unreachable.</p><h3 id="versions-tab" tabindex="-1">Versions tab <a class="header-anchor" href="#versions-tab" aria-label="Permalink to &quot;Versions tab&quot;">​</a></h3><p>Every save keeps a version of the code. You can compare, restore and leave a note on each one — the history is what lets you touch a service already in use without fear.</p><h3 id="publishing" tabindex="-1">Publishing <a class="header-anchor" href="#publishing" aria-label="Permalink to &quot;Publishing&quot;">​</a></h3><p>An own service only goes live once published, and it runs on the <strong>port</strong> on its record. Each service has its own.</p><div class="warning custom-block"><p class="custom-block-title">Publishing is reconciled, not instantaneous</p><p>The process serving the MCPs periodically compares what is live with what is in the database. After publishing, the endpoint appears within seconds — not at the same instant as the click.</p></div><p><strong>Test</strong> calls the tool straight from the screen, with no agent involved. It is how you tell &quot;the tool is wrong&quot; apart from &quot;the model did not choose it&quot;.</p>',25)])])}const b=t(i,[["render",l]]);export{g as __pageData,b as default};
